INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(39936, 166, 157, '<td valign="top">I really love the contrast on this one. Great depth of field...very nice framing.</td>', 'I really love the contrast on this one. Great depth of field...very nice framing.', '2002-03-01 11:08:00.000000', NULL, 1),
(39937, 166, 347, '<td valign="top">Could perhaps have framed out the two pods on the RHS? Okay, I''m being picky.</td>', 'Could perhaps have framed out the two pods on the RHS? Okay, I''m being picky.', '2002-03-01 12:58:00.000000', NULL, 1),
(39938, 166, 322, '<td valign="top">Its hard to find your focus point in this shot I see at least 3 separated areas in focus. Hard on the eyes, smaller aperture please.</td>', 'Its hard to find your focus point in this shot I see at least 3 separated areas in focus. Hard on the eyes, smaller aperture please.', '2002-03-01 13:19:00.000000', NULL, 1),
(39939, 166, 156, '<td valign="top">heehee, cute caption</td>', 'heehee, cute caption', '2002-03-01 13:38:00.000000', NULL, 1),
(39940, 166, 222, '<td valign="top">not a very intersting subject</td>', 'not a very intersting subject', '2002-03-01 13:57:00.000000', NULL, 1),
(39941, 166, 210, '<td valign="top">The focus is a bit scattered.</td>', 'The focus is a bit scattered.', '2002-03-01 15:02:00.000000', NULL, 1),
(39942, 166, 113, '<td valign="top">Nice color.  A little blurring, but nice detail.</td>', 'Nice color.  A little blurring, but nice detail.', '2002-03-02 08:54:00.000000', NULL, 1),
(39943, 166, 391, '<td valign="top">out of focus</td>', 'out of focus', '2002-03-03 21:04:00.000000', NULL, 1),
(39944, 166, 413, '<td valign="top">The weathered ''flowers'' really stand out in this picture.</td>', 'The weathered ''flowers'' really stand out in this picture.', '2002-03-05 16:21:00.000000', NULL, 1),
(39945, 166, 436, '<td valign="top">good tone and texture. nice depth of field</td>', 'good tone and texture. nice depth of field', '2002-03-07 14:39:00.000000', NULL, 1),
(39946, 166, 459, '<td valign="top">Ok close up.  Green background hides green stems.  Flowers uninteresting</td>', 'Ok close up.  Green background hides green stems.  Flowers uninteresting', '2002-03-08 18:22:00.000000', NULL, 0),
(39947, 166, 1, '<td valign="top">Had they been blooming, I feel the shot would''ve looked much better.  Technically done well though.</td>', 'Had they been blooming, I feel the shot would''ve looked much better.  Technically done well though.', '2002-03-10 21:12:00.000000', NULL, 0),
(39948, 166, 261, '<td valign="top">In this photo I was trying to capture the beauty of the ugliness.. hence the title ''Ugly Duckling''.<br/>Thanks for all your comments, I reckon they all helped.<br/>For RED I found myself thinking a lot more about my photos and composition .. keeping in mind all criticismsINSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(40144, 190, 142, '<td valign="top">Nice picture.  I like the angle.</td>', 'Nice picture.  I like the angle.', '2002-03-01 14:51:00.000000', NULL, 1),
(40145, 190, 113, '<td valign="top">This is nice, the colors are very nice.</td>', 'This is nice, the colors are very nice.', '2002-03-02 09:16:00.000000', NULL, 1),
(40146, 190, 1, '<td valign="top">Interesting angle, but it seems to be lacking something.</td>', 'Interesting angle, but it seems to be lacking something.', '2002-03-06 09:27:00.000000', NULL, 1),
(40147, 190, 193, '<td valign="top">The back-lighting is neat, but the focal plant loses some radiance.  The perspective is great.</td>', 'The back-lighting is neat, but the focal plant loses some radiance.  The perspective is great.', '2002-03-06 15:49:00.000000', NULL, 1),
(40148, 190, 459, '<td valign="top">Odd composition.  Cluttered background</td>', 'Odd composition.  Cluttered background', '2002-03-08 18:37:00.000000', NULL, 0),
(40149, 191, 222, '<td valign="top">subject matter is banal</td>', 'subject matter is banal', '2002-03-01 14:10:00.000000', NULL, 1),
(40150, 191, 222, '<td valign="top">subject matter is banal</td>', 'subject matter is banal', '2002-03-01 14:10:00.000000', NULL, 1),
(40151, 191, 322, '<td valign="top">Too many blown highlights for me. Get closer and eliminate some of the surrounding highlights (top of block especially, at least leaves have some interest).</td>', 'Too many blown highlights for me. Get closer and eliminate some of the surrounding highlights (top of block especially, at least leaves have some interest).', '2002-03-01 14:12:00.000000', NULL, 1),
(40152, 191, 173, '<td valign="top">Great cropping</td>', 'Great cropping', '2002-03-01 17:37:00.000000', NULL, 1),
(40153, 191, 245, '<td valign="top">you lost a lot of the detail in the overexposed areas, stop it down!</td>', 'you lost a lot of the detail in the overexposed areas, stop it down!', '2002-03-01 21:57:00.000000', NULL, 1),
(40154, 191, 113, '<td valign="top">Well, its original!</td>', 'Well, its original!', '2002-03-02 09:17:00.000000', NULL, 1),
(40155, 191, 1, '<td valign="top">Seems a little over exposed at the bottom right and top left corners of the image.  Good idea though.</td>', 'Seems a little over exposed at the bottom right and top left corners of the image.  Good idea though.', '2002-03-06 09:41:00.000000', NULL, 1),
(40156, 191, 459, '<td valign="top">Not very interesting.</td>', 'Not very interesting.', '2002-03-08 18:37:00.000000', NULL, 0),
(40157, 192, 51, '<td valign="top">I like this but the lack of crispness is distracting.</td>', 'I like this but the lack of crispness is distracting.', '2002-03-01 02:46:00.000000', NULL, 1),
(40158, 192, 347, '<td valign="top">Tends to disappear into the background...</td>', 'Tends to disappear into the background...', '2002-03-01 13:08:00.000000', NULL, 1),
(40159, 192, 322, '<td valign="top">Good! I hope you tried this with a very delicate touch of flash as well, maybe even a flashlight - something to give it some ''pop'' - a few spectral highlights.</td>', 'Good! I hope you tried this with a very delicate touch of flash as well, maybe even a flashlight - something to give it some ''pop'' - a few spectral highlights.', '2002-03-01 14:14:00.000000', NULL, 1),
(40160, 192, 173, '<td valign="top">Would have been cool to title the pic ''Anticipation''. Looking at it you find yourself waiting for the melting water to fall off the end of the ice.</td>', 'Would have been cool to title the pic ''Anticipation''. Looking at it you find yourself waiting for the melting water to fall off the end of the ice.', '2002-03-01 17:39:00.000000', NULL, 1),
(40161, 192, 113, '<td valign="top">Not too much detail.  Too bad you couldn''t have caught a ray of sun through it.</td>', 'Not too much detail.  Too bad you couldn''t have caught a ray of sun through it.', '2002-03-02 09:19:00.000000', NULL, 1),
(40162, 192, 1, '<td valign="top">Excellent idea, however it doesn''t seem executed well.  The Icicle could''ve been more clear -- or in the sky more so as not to clutter.  Good job though still.</td>', 'Excellent idea, however it doesn''t seem executed well.  The Icicle could''ve been more clear -- or in the sky more so as not to clutter.  Good job though still.', '2002-03-06 09:44:00.000000', NULL, 1),
(40163, 192, 459, '<td valign="top">ok try, but better "Icicle" would make photo more dramatic.  Need color differentiation from foreground to background.</td>', 'ok try, but better "Icicle" would make photo more dramatic.  Need color differentiation from foreground to background.', '2002-03-08 18:41:00.000000', NULL, 0),
(40164, 193, 261, '<td valign="top">nice!... i like the brightness of the flowers contrasted with the dark background</td>', 'nice!... i like the brightness of the flowers contrasted with the dark background', '2002-03-01 01:28:00.000000', NULL, 1),
(40165, 193, 2, '<td valign="top">Is this outdoor?  It seems studio.  But great detail and lighting.</td>', 'Is this outdoor?  It seems studio.  But great detail and lighting.', '2002-03-01 11:08:00.000000', NULL, 1),
